function arisa_register_highlighter_format() {
    if (! current_user_can('edit_posts') && ! current_user_can('edit_pages')) {
        return;
    }
    
    // 註冊 JavaScript
    wp_register_script('arisa-highlighter', '', array('wp-blocks', 'wp-rich-text', 'wp-editor', 'wp-components'), '1.0', true);
    
    wp_add_inline_script('arisa-highlighter', '
        (function(wp) {
            const { registerFormatType } = wp.richText;
            const { __ } = wp.i18n;
            const { RichTextToolbarButton } = wp.blockEditor;
            
            const HIGHLIGHTER_FORMAT = "arisa/highlighter";
            
            registerFormatType(HIGHLIGHTER_FORMAT, {
                title: "Arisa螢光筆",
                tagName: "span",
                className: "arisa-highlighter",
                edit({ isActive, value, onChange }) {
                    return (
                        wp.element.createElement(RichTextToolbarButton, {
                            icon: "marker",
                            title: "Arisa螢光筆",
                            onClick: () => {
                                onChange(
                                    wp.richText.toggleFormat(value, {
                                        type: HIGHLIGHTER_FORMAT,
                                    })
                                );
                            },
                            isActive: isActive
                        })
                    );
                }
            });
            
            // 強制注入編輯器樣式
            function injectEditorStyles() {
                // 檢查是否已經注入過
                if (document.getElementById("arisa-highlighter-editor-styles")) {
                    return;
                }
                
                const style = document.createElement("style");
                style.id = "arisa-highlighter-editor-styles";
                style.innerHTML = `
                    /* 編輯器內樣式 - 使用多重選擇器確保優先級 */
                    .editor-styles-wrapper .arisa-highlighter,
                    .wp-block-editor .arisa-highlighter,
                    .block-editor-writing-flow .arisa-highlighter,
                    .wp-block .arisa-highlighter,
                    .block-editor-rich-text__editable .arisa-highlighter,
                    .rich-text .arisa-highlighter,
                    [data-rich-text-format-boundary] .arisa-highlighter,
                    span.arisa-highlighter {
                        background-image: linear-gradient(transparent 60%, rgba(252, 185, 0, 0.5) 60%) !important;
                        background-color: transparent !important;
                        display: inline !important;
                        position: relative !important;
                    }
                `;
                
                // 確保插入到 head 最後面
                document.head.appendChild(style);
                console.log("Arisa highlighter editor styles injected");
            }
            
            // 多種方式確保樣式載入
            wp.domReady(injectEditorStyles);
            
            if (document.readyState === "loading") {
                document.addEventListener("DOMContentLoaded", injectEditorStyles);
            } else {
                injectEditorStyles();
            }
            
            // 延遲執行確保編輯器完全載入
            setTimeout(injectEditorStyles, 1000);
            setTimeout(injectEditorStyles, 3000);
            
        })(window.wp);
    ');
    
    wp_enqueue_script('arisa-highlighter');
    
    // 同時使用 WordPress 的 CSS 載入方式
    wp_register_style('arisa-highlighter-editor-css', false);
    wp_add_inline_style('arisa-highlighter-editor-css', '
        .editor-styles-wrapper .arisa-highlighter,
        .wp-block-editor .arisa-highlighter,
        .block-editor-writing-flow .arisa-highlighter,
        .wp-block .arisa-highlighter,
        .block-editor-rich-text__editable .arisa-highlighter,
        .rich-text .arisa-highlighter {
            background-image: linear-gradient(transparent 60%, rgba(252, 185, 0, 0.5) 60%) !important;
            background-color: transparent !important;
        }
    ');
    wp_enqueue_style('arisa-highlighter-editor-css');
}
add_action('enqueue_block_editor_assets', 'arisa_register_highlighter_format');

