/**
 * Convert Rank Math FAQ Block Into Accordion
 */
function turn_rm_faq_to_accordion() {
	?>
<style>
/* --- Rank Math FAQ Accordion Styles --- */
#rank-math-faq .rank-math-list-item {
	margin-bottom: 1em;
	margin-top: 1em;
	border-bottom: 1px solid #fff;
}

.rank-math-question {
	cursor: pointer;
	position: relative;
	display: block;
	padding-right: 1em;
	margin-right: 1em;
	font-weight: 300;
	margin-bottom: 30px;
}

.rank-math-question:after {
	position: absolute;
	right: 5px;
	top: 0;
	content: "2715";
	transform: rotate(-45deg);
	transition: all 150ms ease-in-out;
}

.rank-math-question.collapse:after {
	transform: rotate(0deg);
}

.rank-math-question:hover {
	opacity: 0.8;
}
</style>
<script>
(function ($) {

	var rankMathFaq = {
		accordion: function () {
			
			.find('.rank-math-question').click(function () {  
				//Expand or collapse this panel
				.nextAll('.rank-math-answer').eq(0).slideToggle('fast', function () {
					if (.hasClass('collapse')) {
						.removeClass('collapse');
					}
					else {
						.addClass('collapse');
					}
				});
				//Hide the other panels
				.not(.nextAll('.rank-math-answer').eq(0)).slideUp('fast');
			});

			.click(function () {
				.not().removeClass('collapse');
				if (.hasClass('collapse')) {
					.removeClass('collapse');
				}
				else {
					.addClass('collapse');
				}
			});
		}
	};

	rankMathFaq.accordion();

})(jQuery);
</script>
	<?php
}
add_action( 'wp_footer', 'turn_rm_faq_to_accordion' );
